-- BrandKraf — BM translation batch 15: FULL-DEPTH (5 articles, net-new). Run AFTER blog-i18n-migration.sql.
-- Faithful, section-for-section translations of the English articles. Content dollar-quoted ($ms$...$ms$).

update public.blog_posts set
  title_ms = 'Pasaran vs Laman Web Anda Sendiri: Di Mana Anda Patut Menjual?',
  excerpt_ms = 'Shopee dan Lazada, atau kedai dalam talian anda sendiri? Bandingkan jangkauan, margin, kawalan, dan data supaya anda boleh memutuskan di mana hendak menjual — dan mengapa kebanyakan jenama akhirnya melakukan kedua-duanya.',
  content_ms = $ms$<p>Patutkah anda menjual di pasaran seperti Shopee dan Lazada, atau membina laman web anda sendiri? Ia salah satu soalan paling biasa yang dihadapi penjual Malaysia. Jawapan jujur untuk kebanyakan jenama yang berkembang ialah "kedua-duanya" — tetapi memahami pertukaran membantu anda menyusunnya dengan betul.</p>
<blockquote>Di pasaran anda menyewa penonton. Di kedai anda sendiri anda memilikinya. Jenama bijak melakukan kedua-duanya — dan memindahkan nilai kepada apa yang mereka miliki.</blockquote>
<h2>Hujah untuk pasaran</h2>
<p>Pasaran membawa trafik segera dan besar-besaran — berjuta-juta pembeli sudah berada di sana dan sedia membeli. Ia mudah untuk dimulakan, dipercayai oleh pembeli, dan bagus untuk penemuan. Untuk penjual baharu, ia selalunya laluan terpantas ke jualan pertama tanpa berbelanja pada trafik.</p>
<h2>Kelemahan pasaran</h2>
<p>Anda membayar yuran dan komisen, bersaing sengit pada harga, tidak boleh membina banyak jenama, dan — yang penting — tidak memiliki hubungan atau data pelanggan. Anda penyewa: platform menetapkan peraturan dan menyimpan pelanggan.</p>
<h2>Hujah untuk laman web anda sendiri</h2>
<p>Kedai anda sendiri memberi anda margin lebih baik (tiada komisen pasaran), kawalan penuh penjenamaan dan pengalaman, dan pemilikan data pelanggan untuk e-mel, penyasaran semula, dan pengekalan. Ia aset yang anda bina ekuiti di dalamnya dari masa ke masa.</p>
<h2>Kelemahan kedai anda sendiri</h2>
<p>Anda perlu memacu trafik anda sendiri melalui iklan, SEO, sosial, dan kandungan — tiada penonton terbina dalam. Ia memerlukan lebih usaha dan kemahiran pemasaran, tetapi ganjarannya ialah pemilikan dan margin.</p>
<h2>Mengapa kebanyakan jenama menggunakan kedua-duanya</h2>
<p>Langkah menang bagi ramai: gunakan pasaran untuk jangkauan dan penemuan, sambil membina kedai anda sendiri untuk margin, data, dan pengekalan — dan secara beransur memindahkan pelanggan berulang ke saluran yang anda miliki. Anda mendapat yang terbaik daripada kedua-dua dunia.</p>
<h2>Cara menyusunnya</h2>
<p>Jika anda baru bermula dan memerlukan jualan pantas, mula di pasaran. Apabila anda berkembang, bina kedai anda sendiri dan gunakan e-mel dan WhatsApp untuk mengekalkan pelanggan di sana. Lihat <a href="/ms/blog/ecommerce-platform-comparison-malaysia">perbandingan platform</a> dan <a href="/ms/blog/email-marketing-automation-guide">panduan automasi e-mel</a> kami.</p>
<h2>Soalan lazim</h2>
<h3>Patutkah pemula bermula di pasaran?</h3>
<p>Selalunya ya — trafik segera dan kepercayaan menjadikan jualan pertama lebih mudah semasa anda belajar. Tambah kedai anda sendiri apabila berkembang.</p>
<h3>Mengapa membina kedai sendiri jika pasaran ada lebih trafik?</h3>
<p>Untuk margin, penjenamaan, dan memiliki data serta hubungan pelanggan — asas pertumbuhan jangka panjang yang menguntungkan.</p>
<h3>Bolehkah saya menjalankan kedua-duanya pada masa yang sama?</h3>
<p>Ya, dan kebanyakan jenama yang berkembang berbuat demikian. Gunakan pasaran untuk jangkauan dan kedai anda untuk margin dan pengekalan.</p>
<h3>Bagaimana saya memindahkan pelanggan pasaran ke kedai saya sendiri?</h3>
<p>Galakkan pembeli berulang ke laman anda dengan faedah kesetiaan lebih baik, dan tangkap e-mel serta pilihan WhatsApp untuk memasarkan kepada mereka secara langsung.</p>
<p>BrandKraf membantu jenama Malaysia menang di setiap saluran. Terokai <a href="/ms/guides/ecommerce-marketing">panduan e-dagang</a> kami, <a href="/ms/portfolio/website-development">perkhidmatan laman web</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'marketplace-vs-own-website';

update public.blog_posts set
  title_ms = 'Automasi Pemasaran E-mel: Aliran yang Menjual secara Autopilot',
  excerpt_ms = 'Automasi e-mel membolehkan anda menjual sambil anda tidur. Pelajari aliran e-mel automatik yang penting — selamat datang, troli ditinggalkan, selepas pembelian, dan tarik balik — yang setiap perniagaan patut jalankan.',
  content_ms = $ms$<p>E-mel masih salah satu saluran pemasaran ROI tertinggi — dan automasi yang menjadikannya tanpa usaha. Daripada menghantar kempen secara manual, anda sediakan aliran sekali dan ia berjalan selama-lamanya, menjual secara autopilot. Inilah automasi penting yang setiap perniagaan patut ada.</p>
<blockquote>Kempen ialah kerja yang anda ulang. Automasi ialah kerja yang anda lakukan sekali dan peroleh daripadanya selama-lamanya.</blockquote>
<h2>Kempen vs automasi</h2>
<p>Kempen ialah letusan e-mel sekali sahaja (promosi, surat berita). Automasi ialah aliran tercetus yang menghantar secara automatik berdasarkan tingkah laku — pendaftaran baharu, troli ditinggalkan, pembelian. Automasi secara senyap memacu sebahagian besar hasil e-mel kerana ia mencapai orang pada saat yang tepat.</p>
<h2>Aliran selamat datang</h2>
<p>Apabila seseorang menyertai senarai anda, urutan selamat datang automatik memperkenalkan jenama anda, menetapkan jangkaan, dan selalunya membuat tawaran pertama. Pelanggan baharu berada pada minat puncak — aliran selamat datang yang baik menukar lebih ramai daripada mereka berbanding mana-mana e-mel kemudian. Lihat <a href="/ms/blog/welcome-email-sequence">panduan urutan selamat datang</a> kami.</p>
<h2>Aliran troli ditinggalkan</h2>
<p>Untuk e-dagang, ini automasi ROI tertinggi yang ada. Apabila pembeli meninggalkan item dalam troli mereka, peringatan automatik (kadangkala dengan insentif) memulihkan sebahagian bermakna daripada jualan itu. Lihat <a href="/ms/blog/abandoned-cart-email-strategy">panduan troli ditinggalkan</a> dan <a href="/ms/blog/reduce-cart-abandonment">cara mengurangkan pengabaian troli</a> kami.</p>
<h2>Aliran selepas pembelian</h2>
<p>Selepas seseorang membeli, automasi mengekalkan hubungan: pengesahan pesanan, kemas kini penghantaran, tip cara guna, permintaan ulasan, dan tawaran susulan. Ini memacu pembelian berulang dan ulasan — asas <a href="/ms/blog/customer-retention-loyalty-marketing">pengekalan</a>.</p>
<h2>Aliran tarik balik</h2>
<p>Apabila pelanggan menjadi senyap, urutan tarik balik automatik — semakan, insentif, "kami rindukan anda" — mengaktifkan semula bilangan yang mengejutkan pada kos hampir sifar. Ia jauh lebih murah daripada memperoleh pelanggan baharu.</p>
<h2>Mula ringkas</h2>
<p>Anda tidak memerlukan setiap aliran sekali gus. Mula dengan aliran selamat datang (semua orang memerlukannya) dan, jika anda menjual dalam talian, aliran troli ditinggalkan. Kedua-dua itu sahaja selalunya membayar alat e-mel anda berkali ganda. Tambah lagi sambil anda berkembang.</p>
<h2>Soalan lazim</h2>
<h3>Adakah automasi e-mel sukar disediakan?</h3>
<p>Alat e-mel moden menjadikannya visual dan mudah didekati. Mula dengan satu aliran ringkas dan kembangkan — anda tidak perlu jadi teknikal.</p>
<h3>Automasi mana patut saya bina dahulu?</h3>
<p>Aliran selamat datang untuk semua orang, tambah aliran troli ditinggalkan jika anda menjual dalam talian. Kedua-duanya berimpak tinggi dan pantas disediakan.</p>
<h3>Adakah automasi e-mel terasa tidak peribadi?</h3>
<p>Dilakukan dengan baik, sebaliknya — ia mencapai orang pada saat yang betul dengan mesej relevan, yang terasa lebih peribadi daripada letusan generik.</p>
<h3>Apa alat yang saya perlukan?</h3>
<p>Kebanyakan platform e-mel PKS termasuk automasi. Pilih satu yang sesuai dengan bajet anda dan bersepadu dengan kedai anda.</p>
<p>BrandKraf membina sistem e-mel dan automasi yang menjual secara autopilot. Terokai <a href="/ms/guides/email-automation">panduan e-mel dan automasi</a> kami, <a href="/ms/portfolio/ai-driven-marketing">perkhidmatan pemasaran AI</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'email-marketing-automation-guide';

update public.blog_posts set
  title_ms = 'Cara Membina Senarai E-mel dari Awal',
  excerpt_ms = 'Senarai e-mel ialah aset paling bernilai yang anda miliki — talian terus kepada penonton anda yang tiada algoritma mengawal. Pelajari cara membina satu dari sifar, secara beretika dan pantas.',
  content_ms = $ms$<p>Pengikut media sosial dipinjam; senarai e-mel dimiliki. Algoritma berubah dan jangkauan hilang, tetapi senarai e-mel anda ialah talian terus kepada penonton anda yang tiada platform boleh ambil. Inilah cara membina satu dari awal — dengan cara yang betul.</p>
<blockquote>Anda tidak memiliki pengikut anda — platform memilikinya. Anda memiliki senarai e-mel anda. Bina aset yang anda kawal.</blockquote>
<h2>Mengapa senarai e-mel paling penting</h2>
<p>E-mel secara konsisten menyampaikan salah satu pulangan tertinggi dalam pemasaran, mencapai peti masuk secara langsung (bukan atas belas kasihan algoritma), dan membolehkan anda membina hubungan dan menjual berulang kali kepada orang yang memilih untuk mendengar daripada anda. Ia aset digital paling bernilai yang boleh dibina oleh perniagaan kecil.</p>
<h2>Tawarkan sebab untuk melanggan (magnet petunjuk)</h2>
<p>Orang tidak akan menyertai untuk "kemas kini surat berita". Beri mereka sebab yang menarik — diskaun, panduan berguna, senarai semak, penghantaran percuma, atau akses eksklusif. "Magnet petunjuk" ini ialah faktor tunggal terbesar dalam pertumbuhan senarai. Jadikan nilai jelas dan segera.</p>
<h2>Letakkan borang pendaftaran di tempat ia akan dilihat</h2>
<p>Tambah peluang pendaftaran merentasi laman web anda (pengepala, pengaki, pop timbul, pembayaran), profil sosial anda, dan kandungan anda. Lebih mudah dan lebih kelihatan untuk melanggan, lebih pantas senarai anda berkembang. Jangan tanamnya.</p>
<h2>Gunakan media sosial untuk memacu pendaftaran</h2>
<p>Penonton sosial anda dipinjam — tukarkannya kepada e-mel yang dimiliki. Kerap tuding pengikut ke magnet petunjuk dan pautan pendaftaran anda. Menukar pengikut menjadi pelanggan melindungi anda daripada perubahan algoritma dan risiko platform.</p>
<h2>Sentiasa dapatkan kebenaran</h2>
<p>Hanya e-mel orang yang memilih masuk. Membeli senarai atau menambah orang tanpa kebenaran merosakkan penghantaran, memecahkan kepercayaan, dan boleh melanggar peraturan privasi. Senarai berasaskan kebenaran yang lebih kecil mengatasi senarai besar yang dibeli setiap kali.</p>
<h2>Sambut pelanggan baharu serta-merta</h2>
<p>Saat seseorang menyertai ialah minat puncak. <a href="/ms/blog/welcome-email-sequence">Urutan selamat datang</a> automatik menukar pelanggan segar menjadi peminat dan pelanggan yang terlibat. Sediakannya sebelum anda mula mengumpul pendaftaran.</p>
<h2>Soalan lazim</h2>
<h3>Bagaimana saya mendapat pelanggan pertama saya?</h3>
<p>Tawarkan magnet petunjuk yang bernilai, tambah borang pendaftaran yang kelihatan di mana-mana, dan tuding penonton sosial anda kepadanya. Mula dengan orang yang sudah mengenali anda.</p>
<h3>Patutkah saya membeli senarai e-mel?</h3>
<p>Jangan sekali-kali. Senarai yang dibeli menjejaskan penghantaran, memecahkan kepercayaan, dan jarang menukar. Sentiasa kembang dengan pilihan masuk.</p>
<h3>Apa yang menjadikan magnet petunjuk yang baik?</h3>
<p>Sesuatu yang segera bernilai dan relevan — diskaun, panduan berguna, senarai semak, atau akses eksklusif yang penonton anda benar-benar mahukan.</p>
<h3>Berapa besar senarai saya perlu?</h3>
<p>Penglibatan lebih penting daripada saiz. Senarai kecil yang berminat yang membuka dan membeli mengalahkan yang besar dan acuh tak acuh.</p>
<p>BrandKraf membantu jenama Malaysia membina dan mewangkan senarai e-mel. Terokai <a href="/ms/guides/email-automation">panduan e-mel dan automasi</a> kami, <a href="/ms/portfolio/ai-driven-marketing">perkhidmatan pemasaran AI</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'how-to-build-an-email-list';

update public.blog_posts set
  title_ms = 'Urutan E-mel Selamat Datang yang Menukar Pelanggan',
  excerpt_ms = 'Pelanggan baharu berada pada minat puncak. Pelajari cara membina urutan e-mel selamat datang yang memperkenalkan jenama anda, membina kepercayaan, dan menukar pendaftaran menjadi pembeli kali pertama.',
  content_ms = $ms$<p>Apabila seseorang menyertai senarai e-mel anda, mereka lebih berminat dengan anda daripada yang mereka akan berminat lagi. Urutan e-mel selamat datang memanfaatkan saat itu — memperkenalkan jenama anda, membina kepercayaan, dan membimbing pelanggan baharu ke arah pembelian pertama mereka. Inilah cara membina satu yang menukar.</p>
<blockquote>E-mel selamat datang ialah e-mel paling banyak dibuka yang akan anda hantar. Jangan bazirkannya dengan "terima kasih kerana melanggan" yang polos.</blockquote>
<h2>Mengapa urutan selamat datang sangat penting</h2>
<p>E-mel selamat datang mendapat kadar bukaan dan klik jauh lebih tinggi daripada kempen biasa kerana minat berada pada puncaknya. Urutan yang baik menetapkan nada, membina hubungan, dan menukar pelanggan baharu semasa mereka hangat — dan bukannya membiarkan mereka menyejuk.</p>
<h2>E-mel 1: Sambut dan sampaikan</h2>
<p>Hantar serta-merta. Sambut mereka dengan mesra, sampaikan apa sahaja yang anda janjikan (diskaun, panduan, atau hadiah percuma), dan tetapkan jangkaan untuk apa yang mereka akan terima. Tanggapan pertama penting — jadikannya segera dan sesuai jenama.</p>
<h2>E-mel 2: Ceritakan kisah anda</h2>
<p>Sehari atau dua kemudian, kongsi siapa anda dan apa yang anda perjuangkan. Orang membeli daripada jenama yang mereka berhubung. Kisah jenama yang pendek dan tulen membina kepercayaan yang menjadikan penjualan masa depan lebih mudah — di sinilah <a href="/ms/blog/branding-101-build-a-brand">penjenamaan</a> membuahkan hasil.</p>
<h2>E-mel 3: Tunjukkan nilai dan bukti sosial</h2>
<p>Tonjolkan produk terbaik anda, kandungan paling digemari, dan ulasan atau hasil pelanggan. Menunjukkan nilai dan bukti meyakinkan pelanggan baharu bahawa orang lain mempercayai anda — mengurangkan risiko pembelian pertama.</p>
<h2>E-mel 4: Buat tawaran</h2>
<p>Kini jemput pembelian dengan tawaran yang jelas dan menarik — sebaik-baiknya dengan urgensi lembut. Setelah membina hubungan dan kepercayaan menerusi e-mel sebelumnya, permintaan ini menukar jauh lebih baik daripada nada jualan sejuk.</p>
<h2>Kekalkan ia automatik dan sesuai jenama</h2>
<p>Keseluruhan urutan berjalan secara automatik pada saat seseorang melanggan — lihat <a href="/ms/blog/email-marketing-automation-guide">panduan automasi e-mel</a> kami. Kekalkan suara konsisten, reka bentuk bersih, dan setiap e-mel fokus pada satu tugas. Kemudian ia berfungsi untuk setiap pelanggan baharu, selama-lamanya.</p>
<h2>Soalan lazim</h2>
<h3>Berapa e-mel patut ada dalam urutan selamat datang?</h3>
<p>Sekitar tiga hingga lima berfungsi dengan baik — cukup untuk menyambut, membina kepercayaan, dan membuat tawaran tanpa membebankan. Kualiti mengatasi kuantiti.</p>
<h3>Berapa jarak antara e-mel patut?</h3>
<p>Biasanya sehari atau dua antara setiap satu, semasa minat masih tinggi. Uji masa untuk penonton anda.</p>
<h3>Patutkah e-mel pertama termasuk tawaran?</h3>
<p>Sampaikan apa yang anda janjikan dahulu dan sambut mereka; simpan tawaran kuat untuk selepas anda membina sedikit kepercayaan. Jika mereka menyertai untuk diskaun, hormatinya serta-merta.</p>
<h3>Adakah saya perlukan ini jika saya bukan e-dagang?</h3>
<p>Ya — setiap perniagaan mendapat manfaat daripada menyambut dan memupuk pelanggan baharu, sama ada matlamatnya jualan, tempahan, atau pertanyaan.</p>
<p>BrandKraf mereka bentuk aliran selamat datang yang menukar untuk jenama Malaysia. Terokai <a href="/ms/guides/email-automation">panduan e-mel dan automasi</a> kami, <a href="/ms/portfolio/ai-driven-marketing">perkhidmatan pemasaran AI</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'welcome-email-sequence';

update public.blog_posts set
  title_ms = 'E-mel Troli Ditinggalkan: Pulihkan Jualan Hilang secara Automatik',
  excerpt_ms = 'E-mel troli ditinggalkan ialah automasi ROI tertinggi dalam e-dagang. Pelajari cara menyediakan urutan pemulihan yang memenangi semula pembeli yang pergi sebelum membeli.',
  content_ms = $ms$<p>Setiap troli yang ditinggalkan ialah hampir-jualan — pembeli yang mahukan produk anda tetapi terganggu. E-mel troli ditinggalkan membuat susulan secara automatik dan memulihkan sebahagian bermakna daripada hasil yang hilang itu. Untuk e-dagang, ia automasi ROI tertinggi tunggal yang boleh anda jalankan.</p>
<blockquote>Mereka sudah memilih produk itu. E-mel troli ditinggalkan hanya menghapuskan apa sahaja yang menghentikan mereka daripada mengklik beli.</blockquote>
<h2>Mengapa e-mel ini sangat menukar</h2>
<p>Tidak seperti pemasaran sejuk, e-mel troli ditinggalkan mencapai seseorang yang sudah menambah produk anda ke troli mereka. Niatnya terbukti; anda hanya mengingatkan dan meyakinkan. Sebab itulah ia secara konsisten mengatasi hampir setiap e-mel lain yang anda hantar.</p>
<h2>E-mel 1: Peringatan (dalam beberapa jam)</h2>
<p>Hantar e-mel pertama beberapa jam selepas pengabaian, semasa niat masih segar. Kekalkan ia ringkas: ingatkan mereka apa yang mereka tinggalkan, tunjukkan produk, dan jadikan ia satu klik untuk kembali ke troli mereka. Selalunya tolakan lembut sudah memadai.</p>
<h2>E-mel 2: Tangani bantahan (keesokan hari)</h2>
<p>Jika mereka belum kembali, tangani apa yang mungkin menahan mereka — kos penghantaran, kepercayaan, saiz, atau soalan. Tambah ulasan, dasar pemulangan jelas, dan jaminan. Menghapuskan keraguan memulihkan pembeli yang teragak-agak.</p>
<h2>E-mel 3: Insentif (pilihan)</h2>
<p>E-mel terakhir boleh menawarkan insentif kecil — penghantaran percuma atau diskaun sederhana — untuk menolak mereka yang teragak-agak. Gunakan ini dengan berhati-hati supaya pembeli tidak belajar meninggalkan dengan sengaja; kadangkala urgensi ("troli anda hampir luput") berfungsi lebih baik daripada diskaun.</p>
<h2>Pasangkan dengan pembetulan di laman</h2>
<p>E-mel pemulihan berfungsi paling baik bersama pembayaran yang lancar. Kurangkan mengapa troli ditinggalkan sejak awal — lihat <a href="/ms/blog/reduce-cart-abandonment">cara mengurangkan pengabaian troli</a>. Lebih sedikit pengabaian tambah e-mel pemulihan yang kukuh ialah gabungan yang menang.</p>
<h2>Lanjutkan ke WhatsApp</h2>
<p>Di Malaysia, peringatan troli WhatsApp boleh lebih berkesan daripada e-mel berkat kadar bukaan yang tinggi. Gabungkan kedua-dua saluran untuk pemulihan maksimum — lihat <a href="/ms/blog/whatsapp-marketing-malaysian-businesses">panduan pemasaran WhatsApp</a> kami.</p>
<h2>Soalan lazim</h2>
<h3>Berapa e-mel troli ditinggalkan patut saya hantar?</h3>
<p>Biasanya dua hingga tiga — peringatan segera, pengendali bantahan, dan insentif pilihan. Lebih daripada itu berisiko mengganggu orang.</p>
<h3>Bila e-mel pertama patut dihantar?</h3>
<p>Dalam beberapa jam pengabaian, semasa niat masih tinggi. Kelajuan menambah baik pemulihan.</p>
<h3>Patutkah saya sentiasa menawarkan diskaun?</h3>
<p>Tidak — pimpin dengan peringatan dan jaminan. Gunakan insentif kecil hanya jika perlu, atau pembeli mungkin meninggalkan dengan sengaja untuk mendapatkannya.</p>
<h3>Adakah ini berfungsi untuk WhatsApp juga?</h3>
<p>Ya — peringatan troli WhatsApp selalunya mempunyai kadar bukaan lebih tinggi di Malaysia. Menggabungkan e-mel dan WhatsApp memaksimumkan pemulihan.</p>
<p>BrandKraf menyediakan aliran pemulihan yang memenangi semula jualan hilang. Terokai <a href="/ms/guides/email-automation">panduan e-mel dan automasi</a> kami, <a href="/ms/portfolio/chatbot-development">perkhidmatan automasi</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'abandoned-cart-email-strategy';
